<?php
declare(strict_types=1);
require_once __DIR__ . '/../auth_check.php';
AccessManager::requirePageAccess();
require_once __DIR__ . '/../model/Database.php';
require_once __DIR__ . '/../model/Devis.php';
require_once __DIR__ . '/../services/ChantierCreationGuardService.php';
require_once __DIR__ . '/../services/ChantierFinancialComplianceService.php';

$pdo = Database::getConnection();
$guard = new ChantierCreationGuardService($pdo);
$compliance = new ChantierFinancialComplianceService($pdo);
$devisModel = new Devis($pdo);
if (empty($_SESSION['chantier_regularisation_csrf'])) $_SESSION['chantier_regularisation_csrf'] = bin2hex(random_bytes(32));
$selectedId = (int) ($_GET['id'] ?? $_POST['chantier_id'] ?? 0);
$flash = '';
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    try {
        if (!hash_equals((string) $_SESSION['chantier_regularisation_csrf'], (string) ($_POST['_csrf'] ?? ''))) throw new RuntimeException('Jeton CSRF invalide.');
        if (empty($_SESSION['permissions']['modifier_devis_chantier_actif'])) throw new DomainException('Droit spécial requis pour modifier le devis et le déboursé d’un chantier en cours.');
        $pdo->beginTransaction();
        if (($_POST['regularisation_action'] ?? '') === 'attach_quote') {
            $newDevisId = (int)($_POST['new_devis_id'] ?? 0);
            $quoteStatement = $pdo->prepare('SELECT id,client_id FROM devis_banamur WHERE id=:id AND NOT EXISTS(SELECT 1 FROM chantier_banamur c WHERE c.devis_id=devis_banamur.id AND c.archived_at IS NULL AND c.id<>:chantier)');
            $quoteStatement->execute(['id'=>$newDevisId,'chantier'=>$selectedId]);
            $quote = $quoteStatement->fetch(PDO::FETCH_ASSOC);
            if(!$quote) throw new DomainException('Le devis choisi est introuvable ou déjà utilisé par un autre chantier actif.');
            $pdo->prepare('UPDATE chantier_banamur SET devis_id=:devis,client_id=:client WHERE id=:chantier AND archived_at IS NULL')->execute(['devis'=>$newDevisId,'client'=>(int)$quote['client_id'],'chantier'=>$selectedId]);
            $flash='Devis rattaché. Complétez maintenant ses montants, son planning, son déboursé et son échéancier.';
        } else {
        $devisId = (int) ($_POST['devis_id'] ?? 0);
        $quoteTotalHt = round((float)($_POST['quote_total_ht'] ?? 0),2);
        $quoteTotalTtc = round((float)($_POST['quote_total_ttc'] ?? 0),2);
        if($quoteTotalHt<=0||$quoteTotalTtc<=0||$quoteTotalTtc<$quoteTotalHt) throw new DomainException('Renseignez des montants HT et TTC valides. Le TTC ne peut pas être inférieur au HT.');
        $pdo->prepare('UPDATE devis_banamur SET total_ht=:ht,total_ttc=:ttc WHERE id=:id')->execute(['ht'=>$quoteTotalHt,'ttc'=>$quoteTotalTtc,'id'=>$devisId]);
        $schedule = json_decode((string) ($_POST['billing_schedule_json'] ?? '[]'), true);
        $guard->savePreparation($devisId, (string) ($_POST['project_start_date'] ?? ''), (string) ($_POST['project_end_date'] ?? ''), is_array($schedule) ? $schedule : []);
        $debourseRows=is_array($_POST['debourse']??null)?$_POST['debourse']:[];$debourseTotal=0.0;
        foreach($debourseRows as $lineId=>$item)$debourseTotal+=max(0,(float)($item['amount']??0));
        if($debourseTotal<=0)throw new DomainException('Ajoutez au moins un montant de déboursé.');
        if($debourseTotal>$quoteTotalTtc*.65+.01)throw new DomainException('Le total déboursé dépasse 65 % du TTC du devis. Maximum autorisé : '.number_format($quoteTotalTtc*.65,0,',',' ').' FCFA.');
        foreach($debourseRows as $lineId=>$item){$amount=max(0,(float)($item['amount']??0));if($amount<=0)continue;$devisModel->saveDebourseLigne($devisId,(int)$lineId,$amount,(int)($item['responsable_id']??($_SESSION['user_id']??0)),(string)($item['start']??''),(string)($item['end']??''));}
        $assessment = $compliance->auditOne($selectedId, $devisId);
        if ($assessment['status'] !== 'compliant') throw new DomainException((string) $assessment['issue']);
        $flash = 'Chantier régularisé : devis, planning, déboursé et échéancier sont maintenant conformes.';
        }
        $pdo->commit();
    } catch (Throwable $e) { if ($pdo->inTransaction()) $pdo->rollBack(); $flash = $e->getMessage(); }
}
$rows = $pdo->query("SELECT c.id,c.code,c.titre,c.devis_id,d.numero_devis,d.total_ht,d.total_ttc,d.date_emission,d.project_start_date,d.project_end_date,cl.nom_client FROM chantier_banamur c LEFT JOIN devis_banamur d ON d.id=c.devis_id LEFT JOIN client_banamur cl ON cl.id_client=c.client_id WHERE c.archived_at IS NULL ORDER BY c.id DESC")->fetchAll(PDO::FETCH_ASSOC) ?: [];
$incomplete = [];
foreach ($rows as &$row) {
    $assessment = $compliance->auditOne((int)$row['id'], (int)$row['devis_id']);
    $row['regularisation_error'] = (string)($assessment['issue'] ?? '');
    $row['regularisation_issues'] = (array)($assessment['issues'] ?? []);
    if ($assessment['status'] === 'incomplete') $incomplete[] = $row;
}
unset($row);
$selected = null;
foreach ($rows as $row) if ((int) $row['id'] === $selectedId) { $selected = $row; break; }
$schedule = $selected ? $guard->schedule((int) $selected['devis_id']) : [];
$quoteLines=[];$debourseByLine=[];$lineTotal=0.0;$availableQuotes=[];
if($selected&&((int)$selected['devis_id'])>0){$lineStatement=$pdo->prepare('SELECT id,designation,total FROM ligne_devis_banamur WHERE devis_id=:id ORDER BY id');$lineStatement->execute(['id'=>(int)$selected['devis_id']]);$quoteLines=$lineStatement->fetchAll(PDO::FETCH_ASSOC)?:[];foreach($quoteLines as $line)$lineTotal+=(float)$line['total'];$debitStatement=$pdo->prepare('SELECT * FROM debourse_banamur WHERE devis_id=:id ORDER BY id');$debitStatement->execute(['id'=>(int)$selected['devis_id']]);foreach($debitStatement->fetchAll(PDO::FETCH_ASSOC)?:[] as $debit)$debourseByLine[(int)$debit['ligne_devis_id']]=$debit;}
if($selected&&((int)$selected['devis_id'])<=0){$availableQuotes=$pdo->query("SELECT d.id,d.numero_devis,d.total_ttc,cl.nom_client FROM devis_banamur d LEFT JOIN client_banamur cl ON cl.id_client=d.client_id WHERE NOT EXISTS(SELECT 1 FROM devis_archives a WHERE a.devis_id=d.id AND a.restored_at IS NULL) AND NOT EXISTS(SELECT 1 FROM chantier_banamur c WHERE c.devis_id=d.id AND c.archived_at IS NULL) ORDER BY d.created_at DESC LIMIT 500")->fetchAll(PDO::FETCH_ASSOC)?:[];}
function chantierRegularisationAction(array $row,string $issue):array{
    $chantier=(int)$row['id'];$devis=(int)($row['devis_id']??0);
    if($devis<=0||str_contains($issue,'introuvable')||str_contains($issue,'non rattaché'))return['url'=>'?id='.$chantier.'#atelier','label'=>'Rattacher un devis','icon'=>'fa-link'];
    if(str_contains($issue,'Montant TTC')||str_contains($issue,'ligne dans le devis'))return['url'=>'../devis/modifier.php?devisId='.$devis.'#devis-lines','label'=>'Modifier le devis','icon'=>'fa-file-pen'];
    if(str_contains($issue,'Planning général'))return['url'=>'../devis/planning.php?devisId='.$devis.'#planning-devis','label'=>'Corriger le planning','icon'=>'fa-calendar-days'];
    if(str_contains($issue,'Échéancier')||str_contains($issue,'Date manquante dans'))return['url'=>'../facturation/echeancier_devis.php?chantier_id='.$chantier.'&devis_id='.$devis.'#echeancier','label'=>'Corriger la facturation','icon'=>'fa-file-invoice-dollar'];
    if(str_contains($issue,'Déboursé')||str_contains($issue,'déboursé'))return['url'=>'../debourse/gerer_debourse.php?devisId='.$devis.'#planning-debourse','label'=>str_contains($issue,'Dates')?'Corriger les dates':'Gérer le déboursé','icon'=>'fa-coins'];
    return['url'=>'?id='.$chantier.'#atelier','label'=>'Corriger cette donnée','icon'=>'fa-screwdriver-wrench'];
}
$pageTitle = 'Régularisation des chantiers actifs'; $activeMenu = 'chantier_regularisation';
require_once __DIR__ . '/../decaissement/includes/header.php';
require_once __DIR__ . '/../decaissement/includes/navbar.php';
?>
