  <div class="reg-table-wrap"><table class="reg-table"><thead><tr><th>Chantier et actions</th><th>Devis / client</th><th>Éléments à régulariser</th><th>Priorité</th></tr></thead><tbody id="regRows">
  <?php foreach($incomplete as $row):$searchText=implode(' ',[(string)$row['code'],(string)$row['titre'],(string)$row['nom_client'],(string)$row['numero_devis'],implode(' ',(array)$row['regularisation_issues'])]);?>
   <tr data-search="<?=htmlspecialchars(mb_strtolower($searchText))?>">
    <td><div class="reg-chantier-inline"><div class="reg-chantier-identity"><span class="reg-code"><?=htmlspecialchars((string)$row['code'])?></span><span class="reg-title"><?=htmlspecialchars((string)$row['titre'])?></span></div><div class="reg-cell-actions"><?php foreach($row['regularisation_issues'] as $issue):$action=chantierRegularisationAction($row,(string)$issue);?><a href="<?=htmlspecialchars($action['url'])?>" title="<?=htmlspecialchars((string)$issue)?>"><i class="fas <?=htmlspecialchars($action['icon'])?>"></i><?=htmlspecialchars($action['label'])?></a><?php endforeach;?></div></div></td>
    <td><strong><?=htmlspecialchars((string)($row['numero_devis']?:'Devis non rattaché'))?></strong><span class="reg-client"><?=htmlspecialchars((string)($row['nom_client']?:'Client non renseigné'))?></span></td>
    <td><div class="reg-issues"><?php foreach($row['regularisation_issues'] as $issue):?><span class="reg-issue"><i class="fas fa-circle-exclamation"></i><?=htmlspecialchars((string)$issue)?></span><?php endforeach;?></div></td>
    <td><span class="reg-priority"><?=count($row['regularisation_issues'])>=3?'HAUTE':'À TRAITER'?></span></td>
   </tr>
