 <div class="mt-6 grid gap-6 lg:grid-cols-[1.05fr_.95fr]"><section class="rounded-2xl border bg-white p-5 shadow-sm"><div class="mb-4 flex items-center justify-between"><div><h2 class="text-xl font-black text-slate-950">Dossiers incomplets</h2><p class="text-sm text-slate-500">Toutes les corrections attendues sont affichées pour chaque chantier.</p></div><div class="flex gap-2"><a href="rapport_regularisation.php" class="rounded-xl bg-slate-900 px-3 py-2 text-sm font-bold text-white">Rapport</a><a href="../chantiers/liste.php" class="rounded-xl border px-3 py-2 text-sm font-bold">Tous les chantiers</a></div></div><div class="space-y-3"><?php foreach($incomplete as $row):?><a href="?id=<?=(int)$row['id']?>" class="block rounded-xl border p-4 transition hover:border-indigo-300 hover:bg-indigo-50/40 <?=selectedId===(int)$row['id']?'border-indigo-500 bg-indigo-50':'border-slate-200'?>"><div class="flex justify-between gap-3"><div><strong class="text-slate-950"><?=htmlspecialchars((string)$row['code'])?> · <?=htmlspecialchars((string)$row['titre'])?></strong><small class="mt-1 block text-slate-500"><?=htmlspecialchars((string)($row['nom_client']?:'Client non identifié'))?> · <?=htmlspecialchars((string)($row['numero_devis']?:'Devis absent'))?></small></div><i class="fas fa-chevron-right text-indigo-600"></i></div><ul class="mt-3 space-y-1 text-sm font-semibold text-rose-700"><?php foreach($row['regularisation_issues'] as $issue):?><li><i class="fas fa-circle-exclamation mr-1"></i><?=htmlspecialchars((string)$issue)?></li><?php endforeach;?></ul></a><?php endforeach;?><?php if(!$incomplete):?><div class="rounded-xl bg-emerald-50 p-6 text-center text-emerald-800"><i class="fas fa-circle-check text-3xl"></i><strong class="mt-3 block">Tous les chantiers actifs sont conformes.</strong></div><?php endif;?></div></section>
 <section id="atelier" class="reg-workspace rounded-2xl border bg-white p-5 shadow-sm"><?php if($selected):?><h2 class="text-xl font-black text-slate-950"><?=htmlspecialchars((string)$selected['code'])?></h2><p class="text-sm text-slate-500"><?=htmlspecialchars((string)($selected['numero_devis']?:'Aucun devis rattaché'))?> · <?=number_format((float)$selected['total_ttc'],0,',',' ')?> FCFA</p>
 <?php if((int)$selected['devis_id']<=0):?><form method="post" class="mt-5 space-y-4"><input type="hidden" name="_csrf" value="<?=htmlspecialchars((string)$_SESSION['chantier_regularisation_csrf'])?>"><input type="hidden" name="regularisation_action" value="attach_quote"><input type="hidden" name="chantier_id" value="<?=(int)$selected['id']?>"><label class="block text-sm font-bold">Sélectionner le devis de ce chantier<select name="new_devis_id" required class="mt-2 w-full rounded-xl border px-3 py-3"><option value="">Rechercher et choisir…</option><?php foreach($availableQuotes as $quote):?><option value="<?=(int)$quote['id']?>"><?=htmlspecialchars((string)$quote['numero_devis'])?> · <?=htmlspecialchars((string)$quote['nom_client'])?> · <?=number_format((float)$quote['total_ttc'],0,',',' ')?> FCFA</option><?php endforeach;?></select></label><p class="rounded-xl bg-blue-50 p-3 text-sm text-blue-900">Le client du chantier sera automatiquement synchronisé avec celui du devis choisi.</p><button class="rounded-xl bg-indigo-700 px-5 py-3 font-black text-white">Rattacher ce devis</button></form>
 <?php else:?><form method="post" id="regularisationForm" data-total="<?=htmlspecialchars((string)$selected['total_ttc'])?>" data-emission="<?=htmlspecialchars((string)$selected['date_emission'])?>" class="mt-5 space-y-5"><input type="hidden" name="_csrf" value="<?=htmlspecialchars((string)$_SESSION['chantier_regularisation_csrf'])?>"><input type="hidden" name="chantier_id" value="<?=(int)$selected['id']?>"><input type="hidden" name="devis_id" value="<?=(int)$selected['devis_id']?>"><input type="hidden" name="billing_schedule_json" id="regularisationScheduleJson">
 <div class="rounded-xl border border-indigo-100 bg-indigo-50/50 p-4"><div class="flex flex-wrap items-center justify-between gap-2"><div><strong class="text-indigo-950">1. Montants du devis</strong><p class="text-xs text-indigo-700">Somme actuelle des lignes : <?=number_format($lineTotal,0,',',' ')?> FCFA</p></div><button type="button" id="useLineTotal" class="rounded-lg bg-white px-3 py-2 text-xs font-bold text-indigo-700 shadow-sm">Reprendre le total des lignes</button></div><div class="mt-3 grid gap-3 sm:grid-cols-2"><label class="text-sm font-bold">Total HT<input id="quoteTotalHt" type="number" min="1" step=".01" name="quote_total_ht" value="<?=htmlspecialchars((string)($selected['total_ht']>0?$selected['total_ht']:$lineTotal))?>" required class="mt-1 w-full rounded-xl border px-3 py-2"></label><label class="text-sm font-bold">Total TTC<input id="quoteTotalTtc" type="number" min="1" step=".01" name="quote_total_ttc" value="<?=htmlspecialchars((string)($selected['total_ttc']>0?$selected['total_ttc']:$lineTotal))?>" required class="mt-1 w-full rounded-xl border px-3 py-2"></label></div></div>
 <div class="rounded-xl border p-4"><strong class="text-slate-950">2. Planning général</strong><div class="mt-3 grid gap-3 sm:grid-cols-2"><label class="text-sm font-bold">Début du planning<input id="regularisationStart" type="date" min="<?=htmlspecialchars((string)$selected['date_emission'])?>" name="project_start_date" value="<?=htmlspecialchars((string)$selected['project_start_date'])?>" required class="mt-1 w-full rounded-xl border px-3 py-2"></label><label class="text-sm font-bold">Fin du planning<input id="regularisationEnd" type="date" min="<?=htmlspecialchars((string)($selected['project_start_date']?:$selected['date_emission']))?>" name="project_end_date" value="<?=htmlspecialchars((string)$selected['project_end_date'])?>" required class="mt-1 w-full rounded-xl border px-3 py-2"></label></div></div>
 <div class="rounded-xl border p-4"><div class="flex justify-between"><strong>3. Échéancier d’encaissement</strong><button type="button" id="regularisationAddRow" class="text-sm font-bold text-indigo-700">+ Ajouter</button></div><div id="regularisationRows" class="mt-3 space-y-2"></div><div class="mt-3 flex justify-between rounded-xl bg-slate-100 p-3 font-black"><span>Total</span><span id="regularisationTotal">0 %</span></div></div>
