<script>(()=>{const form=document.getElementById('regularisationForm');if(!form)return;const emission=form.dataset.emission||'',initial=<?=json_encode($schedule,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>,body=document.getElementById('regularisationRows'),json=document.getElementById('regularisationScheduleJson'),total=document.getElementById('regularisationTotal'),start=document.getElementById('regularisationStart'),end=document.getElementById('regularisationEnd'),ttc=document.getElementById('quoteTotalTtc'),ht=document.getElementById('quoteTotalHt'),debitTotal=document.getElementById('debourseTotal'),debitRatio=document.getElementById('debourseRatio'),format=v=>new Intl.NumberFormat('fr-FR',{maximumFractionDigits:0}).format(v)+' FCFA';function refreshDebourse(){const amount=[...form.querySelectorAll('[data-debit-amount]')].reduce((sum,input)=>sum+(Number(input.value)||0),0),quote=Number(ttc.value)||0,ratio=quote>0?amount/quote*100:0;debitTotal.textContent=format(amount);debitRatio.textContent=ratio.toLocaleString('fr-FR',{maximumFractionDigits:2})+' %';debitRatio.className=ratio>65?'font-black text-rose-700':'font-black text-emerald-700';return amount>0&&ratio<=65}function refresh(){const rows=[...body.children].map(row=>({label:row.querySelector('[data-label]').value.trim(),expected_date:row.querySelector('[data-date]').value,percentage:Number(row.querySelector('[data-percent]').value)||0}));const sum=rows.reduce((v,r)=>v+r.percentage,0),chronological=rows.every((r,i)=>i===0||r.expected_date>=rows[i-1].expected_date);total.textContent=sum.toLocaleString('fr-FR',{maximumFractionDigits:2})+' %';total.className=Math.abs(sum-100)<=.01&&chronological?'text-emerald-700':'text-rose-700';json.value=JSON.stringify(rows);return rows.length&&Math.abs(sum-100)<=.01&&chronological}function add(data={}){const row=document.createElement('div');row.className='grid gap-2 sm:grid-cols-[1fr_145px_100px_36px]';row.innerHTML=`<input data-label required placeholder="Libellé" value="${String(data.label||'').replace(/"/g,'&quot;')}" class="rounded-lg border px-3 py-2"><input data-date required type="date" min="${emission}" value="${data.expected_date||''}" class="rounded-lg border px-3 py-2"><input data-percent required type="number" min=".01" max="100" step=".01" value="${data.percentage||''}" class="rounded-lg border px-3 py-2"><button type="button" class="rounded-lg text-rose-700">×</button>`;row.querySelector('button').onclick=()=>{row.remove();refresh()};row.querySelectorAll('input').forEach(i=>i.oninput=refresh);body.appendChild(row);refresh()}(initial.length?initial:[{label:'Acompte',percentage:50},{label:'Solde',percentage:50}]).forEach(add);document.getElementById('regularisationAddRow').onclick=()=>add();document.getElementById('useLineTotal').onclick=()=>{ht.value=<?=json_encode($lineTotal)?>;ttc.value=<?=json_encode($lineTotal)?>;refreshDebourse()};form.querySelectorAll('[data-debit-amount]').forEach(input=>input.addEventListener('input',refreshDebourse));ttc.addEventListener('input',refreshDebourse);start.onchange=()=>{end.min=start.value;if(end.value&&end.value<start.value)end.value='';form.querySelectorAll('input[type="date"][name*="[start]"]').forEach(input=>input.min=start.value);form.querySelectorAll('input[type="date"][name*="[end]"]').forEach(input=>input.max=end.value)};end.onchange=()=>form.querySelectorAll('input[type="date"][name*="[end]"]').forEach(input=>input.max=end.value);form.onsubmit=e=>{if(!refresh()||!refreshDebourse()){e.preventDefault();alert('Vérifiez l’échéancier à 100 % et le déboursé, qui doit être compris entre 0 et 65 % du TTC.')}};refreshDebourse()})();</script>
<script>(()=>{const input=document.getElementById('regSearch'),rows=[...document.querySelectorAll('#regRows tr')];if(!input)return;input.addEventListener('input',()=>{const query=input.value.trim().toLocaleLowerCase('fr');rows.forEach(row=>row.style.display=!query||String(row.dataset.search||'').includes(query)?'':'none')})})();</script>
